<?php defined('_JEXEC') or die; use Joomla\CMS\HTML\HTMLHelper; use Joomla\CMS\Router\Route; ?>
<div class="container-fluid kaar-booking"><h1>Bookings</h1><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Reference</th><th>Customer</th><th>Trip</th><th>Departure</th><th>Status</th><th>Payment</th><th>Manual action</th></tr></thead><tbody>
<?php foreach($this->items as $item): ?><tr><td><?php echo htmlspecialchars($item['reference'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($item['customer_name'],ENT_QUOTES,'UTF-8'); ?><br><small><?php echo htmlspecialchars($item['customer_email'],ENT_QUOTES,'UTF-8'); ?></small></td><td><?php echo htmlspecialchars($item['service_type'],ENT_QUOTES,'UTF-8'); ?><br><small><?php echo htmlspecialchars($item['origin_text'].' → '.$item['destination_text'],ENT_QUOTES,'UTF-8'); ?></small></td><td><?php echo htmlspecialchars($item['departure_at'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($item['status'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($item['payment_status'],ENT_QUOTES,'UTF-8'); ?></td><td><form action="<?php echo Route::_('index.php?option=com_kaarbooking&task=booking.transition'); ?>" method="post" class="d-flex gap-2"><input type="hidden" name="id" value="<?php echo (int)$item['id']; ?>"><select name="status" class="form-select form-select-sm"><option value="quoted">Quote</option><option value="pending_payment">Await payment</option><option value="confirmed">Confirm</option><option value="allocated">Allocate</option><option value="rejected">Reject</option><option value="cancelled">Cancel</option></select><input name="reason" class="form-control form-control-sm" placeholder="Reason"><button class="btn btn-primary btn-sm" type="submit">Apply</button><?php echo HTMLHelper::_('form.token'); ?></form></td></tr><?php endforeach; ?>
<?php if(!$this->items): ?><tr><td colspan="7">No bookings.</td></tr><?php endif; ?></tbody></table></div></div>
